#!/usr/bin/env python3
# luxarch:no-silenced-staging hook v3 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""Deny MUTATING git commands that silence stderr (`2>/dev/null`).

Earned the hard way: `git add` with a bad pathspec fails ATOMICALLY — it stages nothing,
including the valid files beside it — and reports on stderr. Silence that and the failure is
invisible: the file never enters the commit, and a green LOCAL build hides it (it builds the
working tree, not the commit). That chain broke origin/main once; the deleted type was
referenced for several commits before a rebase finally tripped on it.

Read-only git with `2>/dev/null` (status/show/diff/log/rev-parse, `stash list`) is common and fine.

PreToolUse(Bash): deny `git (add|rm|mv|commit|apply|restore|stash)` + stderr sent nowhere
(`2>/dev/null`, `&>/dev/null`, `>&/dev/null`, `2>&-`, or `>/dev/null` with `2>&1`; a quoted or
variable `/dev/null` too), on the command itself, on a `{ …; }`/`( … )` group around it, by an
earlier `exec 2>/dev/null`, or on a `bash -c` that runs it. git's global options are read as argv
(`git -C <dir> add`), and the shell's nested bodies (`bash -c`, `$(…)`) are judged too. A tool call
this hook cannot read or judge is denied.
"""

from __future__ import annotations

import os
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from _cmdtext import (  # sibling helper, loaded by path
    GitCall,
    MalformedEvent,
    Redirect,
    argv_bodies,
    command_text,
    executable_segments,
    executable_texts,
    expand,
    git_calls,
    guarded,
    load_event,
    redirects,
    segments,
    simple_commands,
    text_field,
    tool_input,
)

MUTATING = re.compile(
    r"\bgit\s+(?:add|rm|mv|commit|apply|restore|stash(?!\s+(?:list|show)\b))\b"
)
MUTATING_SUBS = {"add", "rm", "mv", "commit", "apply", "restore", "stash"}
# stderr sent nowhere, as a regex net over masked text: `2>/dev/null`, `&>/dev/null`,
# `>&/dev/null`, a closed `2>&-`, or stdout sent to /dev/null with `2>&1` following it.
_STDERR_TO_NULL = re.compile(r"(?:^|[\s;(])(?:2>>?|&>>?|>&)\s*/dev/null|2>&-")
_STDOUT_TO_NULL = re.compile(r"(?:^|[\s;(])1?>>?\s*/dev/null")
_STDERR_TO_STDOUT = re.compile(r"2>&1")
_TO_FILE = {">", ">>", ">|"}


def _silenced(masked: str) -> bool:
    if _STDERR_TO_NULL.search(masked):
        return True
    return bool(_STDOUT_TO_NULL.search(masked) and _STDERR_TO_STDOUT.search(masked))


def _discards_stderr(reds: list[Redirect], values: dict[str, str]) -> bool:
    """Do these redirections send stderr nowhere? Targets are read as the shell resolves them
    (quotes, `$N`/`${N}`, `/dev//null`), and descriptors are followed in order, so
    `3>/dev/null 2>&3` sends stderr where fd 3 points. The any-order pairing of `>/dev/null` with
    `2>&1` is kept beside it."""
    fds = {"1": "stdout", "2": "stderr"}
    stdout_null = dup = False
    for r in reds:
        target = expand(r.target, values)
        if target and not target.startswith("&"):
            target = os.path.normpath(target) if target.startswith("/") else target
        null = target == "/dev/null"
        fd = r.fd or "1"
        if r.op in _TO_FILE or (r.op == ">&" and not target.startswith("&")):
            for n in (
                ("1", "2") if r.fd == "&" or (r.op == ">&" and not r.fd) else (fd,)
            ):
                fds[n] = target
        elif r.op == ">&":
            fds[fd] = "closed" if target == "&-" else fds.get(target[1:], target)
        if (r.fd in ("2", "&") and r.op in _TO_FILE and null) or (
            r.op == ">&" and null
        ):
            return True
        if r.fd == "2" and r.op == ">&" and target == "&-":
            return True
        stdout_null = stdout_null or (r.fd in ("", "1") and r.op in _TO_FILE and null)
        dup = dup or (r.fd == "2" and r.op == ">&" and target == "&1")
    return fds["2"] in ("/dev/null", "closed") or (stdout_null and dup)


def _reds(raw: str) -> list[Redirect]:
    return [r for r, _s, _e in redirects(command_text(raw), raw)]


def _mutates(g: GitCall) -> bool:
    return g.sub in MUTATING_SUBS and not (
        g.sub == "stash" and list(g.positionals[:1]) in (["list"], ["show"])
    )


def _mutating_inside(text: str) -> bool:
    try:
        return any(_mutates(g) for g in git_calls(text))
    except MalformedEvent:
        return True


def _group_silenced(text: str) -> bool:
    """`{ git add x; } 2>/dev/null` / `( … ) 2>/dev/null`: a redirection after a group covers it."""
    masked = command_text(text)
    reds = redirects(masked, text)
    for idx, (_r, start, _end) in enumerate(reds):
        before = masked[:start].rstrip()
        if not before.endswith(("}", ")")):
            continue
        close = len(before) - 1
        depth, k = 0, close
        while k >= 0:
            if masked[k] in "})":
                depth += 1
            elif masked[k] in "{(":
                depth -= 1
                if depth == 0:
                    break
            k -= 1
        following = [reds[idx][0]]
        for r2, s2, _e2 in reds[idx + 1 :]:
            if masked[reds[idx][2] : s2].strip():
                break
            following.append(r2)
        if _discards_stderr(following, {}) and _mutating_inside(text[k + 1 : close]):
            return True
    return False


def _exec_silences(text: str) -> bool:
    """`exec 2>/dev/null` silences every later command of the shell."""
    seen_exec = False
    for masked, raw in segments(text):
        rest = _cut(masked, raw)
        if rest.split() == ["exec"] and _discards_stderr(_reds(raw), {}):
            seen_exec = True
        elif seen_exec and MUTATING.search(masked):
            return True
    return False


def _cut(masked: str, raw: str) -> str:
    out = list(masked)
    for _r, start, end in redirects(masked, raw):
        out[start:end] = " " * (end - start)
    return "".join(out)


def _silenced_git_call(raw: str) -> bool:
    for g in git_calls(raw):
        if _mutates(g) and _discards_stderr(_reds(g.raw), dict(g.env)):
            return True
    for sc in simple_commands(raw):  # `bash -c 'git add x' 2>/dev/null`
        bodies = argv_bodies(sc)
        if (
            bodies
            and _discards_stderr(_reds(sc.raw), dict(sc.env))
            and any(_mutating_inside(b) for b in bodies)
        ):
            return True
    return any(_group_silenced(t) or _exec_silences(t) for t in executable_texts(raw))


def main() -> int:
    ev = load_event()
    if ev.get("tool_name") != "Bash":
        return 0
    raw = text_field(tool_input(ev), "command")
    if _silenced_git_call(raw):
        return _deny()
    # Scope the pairing to ONE command segment. A compound line routinely silences an unrelated
    # call earlier on (a docker/build step) and then runs a clean `git add` — matching the whole
    # string reads that as a silenced staging command, and a hook that over-fires gets switched off.
    if not any(
        MUTATING.search(masked) and _silenced(masked)
        for masked, _ in executable_segments(raw)
    ):
        return 0
    return _deny()


def _deny() -> int:
    print(
        "DENIED: never silence stderr on a mutating git command.\n"
        "`git add` fails ATOMICALLY on a bad pathspec — it stages NOTHING and says so on "
        "stderr. Hiding that produces a silently partial commit which a local build cannot "
        "catch. Drop the `2>/dev/null` and read the error.",
        file=sys.stderr,
    )
    return 2


sys.exit(guarded(main, "no-silenced-staging"))
